// src/ui/icons.ts — consumption helpers for the pre-rendered tank icons in
// public/icons/ (generated by `npm run tank:assets` from the shipped models;
// `npm run tank:release:check -- --ids=<id>` gates every tank landing):
//   <id>_angle.webp           3/4 hero  -> garage carousel cards
//   <id>_top.webp             top-down  -> tactical overlays
//   <id>_side.webp            side view -> detail panes
//   <id>_top_silhouette.png   flat white -> minimap blips (tinted green/red)
//   <id>_side_silhouette.png  flat white -> team panels, kill feed, damage panel
//   <id>_armor_side.webp       effective-KE / penetration-information diagram (1024x512, no text)
//   <id>_modules_side.webp     actual module damage-volume diagram (1024x512, no text)
//   <id>_crew_side.webp        actual crew damage-volume diagram (1024x512, no text)
//   <id>_technical.json        the three diagrams' labels, DOM text over them (technicalDiagramLabels.ts)
// Silhouettes ship as white fills so one file serves every team color.
// perf-r3c (Lighthouse): shaded views ship as WebP q90 — the PNG set weighed
// 214-237 KB per 512px icon and dominated page transfer. Silhouettes stay
// PNG: they are tiny flat alpha masks, and Chrome's canvas WebP encoder is
// lossy-only (lossy alpha rings on mask edges).

/** A tank's portrait for a list row or a trigger: its 3/4 view at 256 px (icons/thumbs), every tank in one framing, so a
 *  picker crops them alike (pickers.css .is-tank). */
export const tankThumbUrl = (id: string): string => `/icons/thumbs/${id}_angle.webp`;

/** URL of a generated icon. @param {string} id tank id @param {string} view e.g. 'angle' */
export const iconUrl = (id: string, view: string): string => `/icons/${id}_${view}.${
  /silhouette$/.test(view) ? 'png' : 'webp'}`;

/**
 * Turn a DOM element into a tinted silhouette via CSS mask: the element's
 * background color shows through the icon's alpha. Give the element explicit
 * width/height in CSS.
 * @param {HTMLElement} el
 * @param {string} id tank id
 * @param {string} view icon view name
 * @param {string} color css background color (the tint)
 */
export function maskIcon(el: HTMLElement, id: string, view: string, color: string): void {
  const u = `url(${JSON.stringify(iconUrl(id, view))})`;
  const s = el.style;
  s.webkitMaskImage = u; s.maskImage = u;
  s.webkitMaskSize = 'contain'; s.maskSize = 'contain';
  s.webkitMaskRepeat = 'no-repeat'; s.maskRepeat = 'no-repeat';
  s.webkitMaskPosition = 'center'; s.maskPosition = 'center';
  s.background = color;
}
